-- Returns the waypoint for this character's faction, or nil when only the
-- other faction has a known trainer (the row then keeps its normal
-- open-the-profession click).
function MC.RecipeTrainerWaypoint(recipeID)
    local e = recipeID and T[recipeID]
    if not e then return nil end
    if e.n then return e.n end
    -- UnitFactionGroup is absent outside the client (tests, /reload
    -- ordering); prefer Alliance-or-Horde rather than returning nil.
    local faction = UnitFactionGroup and UnitFactionGroup("player")
    if faction == "Alliance" then return e.a or nil end
    if faction == "Horde" then return e.h or nil end
    return e.a or e.h
end
